local gsub, format, match = string.gsub, string.format, string.match
local sort, concat = table.sort, table.concat
local ch = require("tch.configmigration.convert_helper")
local emc = ch.escape_lua_magic_char

local acs_policy_map = {
  ["Legacy"] = 0,
  ["Interference"] = 1,
  ["Interference&Busy"] = 2,
  ["Optimized"] = 3,
  ["Custom1"] = 4,
  ["Custom2"] = 5,
  ["legacy&noise"] = 6,
}

local function ssid_map_template(wifi_iface)
  return {
    ["ssid"] =          { uci_secname = wifi_iface, uci_option = "ssid" }, -- override uci_secname if need
    ["apisolation"] =   { uci_option = "ap_isolation", value = ch.convert_bool },
    ["any"] =           { uci_option = "public", value = ch.convert_bool },
    ["secmode"] =       { uci_option = "security_mode", value = ch.wireless_convert_secmode },
    ["WEPkey"] =        { uci_option = "wep_key" },
    ["WPAPSKkey"] =     { uci_option = "wpa_psk_key" },
    ["pmksacache"] =    { uci_option = "pmksa_cache", value = ch.convert_bool },
    ["stationhistory"] ={ uci_option = "station_history", value = ch.convert_bool },
    ["maxassociations"]={ uci_option = "max_assoc" },
  }
end

local trace_modules_map = {
    ["level"]  = { uci_option = "level" },
    ["radius"] = { uci_option = "trace_modules", action = "add_list", value = ch.wireless_convert_trace_modules, },
    ["acs"]    = { uci_option = "trace_modules", action = "add_list", value = ch.wireless_convert_trace_modules, },
    ["wps"]    = { uci_option = "trace_modules", action = "add_list", value = ch.wireless_convert_trace_modules, },
    ["dot1x"]  = { uci_option = "trace_modules", action = "add_list", value = ch.wireless_convert_trace_modules, },
    ["remote"] = { uci_option = "trace_modules", action = "add_list", value = ch.wireless_convert_trace_modules, },
  }

local dsd_uf_action_map = {
  ["accept"] = "ACCEPT",
  ["block"]  = "DROP",
}

local function dsd_uf_get_uci_secname(_,_,lt)
  if not lt._maps_store["_uf_uci_secname"] then
     lt._maps_store["_uf_uci_secname"] = lt._maps_store["_ucicmd_result"]
  end
  return lt._maps_store["_uf_uci_secname"]
end

local function dsd_uf_get_mac_from_expr(_,_,lt,g_user_ini)
  return match(g_user_ini["expr.ini"], "add name="..emc(lt._maps_store[1]).." type=mac mac=([:%x]+)")
end

local mobile_apn_map = {
  ["telstra.internet"] = "telstra_internet",
  ["telstra.extranet"] = "telstra_extranet",
  ["telstra.bigpond"] = "telstra_bigpond",
}

local mobile_operator_code_list = {
  ["50501"] = "50501",
  ["50506"] = "50506",
}

local function mobile_network(_,_,lt,g_user_ini)
  local apn = match(g_user_ini["mobile.ini"], "ifconfig intf=Mobile %C*apn=(%S+)")
  return apn and mobile_apn_map[apn] or "other"
end

